#!/usr/bin/env bash
# Some portions generated by Codex. Run only after all diagnostic workloads end.
set -euo pipefail
cd "$(dirname "$0")/../../.."
d=experiments/threadlocal-audit/linear-consumer-workbench
exec 9>experiments/overlay/native-benchmark.lock
flock -x 9
for arm in base depth serializer stack; do
 p="$d/runs/profile-$arm"
 ../toolchain/jdk-25.0.5+8/bin/jfr print --json --stack-depth 128 --events jdk.ExecutionSample,jdk.NativeMethodSample,jdk.ObjectAllocationSample "$p/profile.jfr" > "$p/full-stacks.json"
 python3 "$d/analyze-http-profile.py" "$p/full-stacks.json" > "$p/profile-summary.json"
 python3 "$d/analyze-node-profile.py" "$p" > "$p/node-summary.json"
done
